import fs from 'fs';
const lines = fs.readFileSync('C:/Users/Administrator/Downloads/session.v4.jsonl','utf8').split(/\n/).filter(Boolean);
const byType = {};
const events = [];
for (const line of lines) {
  const o = JSON.parse(line);
  byType[o.type] = (byType[o.type]||0)+1;
  events.push(o);
}
console.log('TYPES', JSON.stringify(byType));
console.log('N', events.length);

function keysOf(o, depth=0) {
  if (!o || typeof o !== 'object') return typeof o;
  return Object.keys(o).join(',');
}

const stepEnds = events.filter(e => e.type==='step/end');
const sample = stepEnds[0];
console.log('STEPEND0 keys', keysOf(sample.data), 'seq', sample.seq);
console.log(JSON.stringify(sample.data).slice(0,800));
const stepStarts = events.filter(e => e.type==='step/start');
console.log('STEPSTART0', JSON.stringify(stepStarts[0].data).slice(0,400), 'seq', stepStarts[0].seq);

const asst = events.filter(e => e.type==='assistant/message');
let zero=0, real=0;
const zeroDetail = [];
for (const a of asst) {
  const u = a.data.usage;
  const stream = a.data.stream;
  const src = a.data.message?.source;
  const hasStream = Array.isArray(stream) && stream.length>0;
  const provider = src?.provider || src?.kind;
  const model = src?.model;
  const replay = !!src?.replayState;
  const stop = src?.replayState?.response?.stopReason;
  const respId = src?.replayState?.response?.responseId;
  const nz = u && (u.inputTokens||u.outputTokens||u.cacheReadTokens||u.totalTokens);
  if (nz) real++;
  else {
    zero++;
    zeroDetail.push({seq:a.seq, t:a.data.turn, s:a.data.step, hasStream, nStream: hasStream?stream.length:0, provider, model, replay, stop, respId: respId?String(respId).slice(0,24):null, usageKeys: u?Object.keys(u):null, msgId: a.data.message?.id?.slice(0,8)});
  }
}
console.log('ASST', asst.length, 'zero', zero, 'real', real);
const providers = {};
for (const z of zeroDetail) {
  const k = [z.provider, z.model, z.replay, z.stop, z.hasStream].join('|');
  providers[k]=(providers[k]||0)+1;
}
console.log('ZERO SHAPE', JSON.stringify(providers,null,2));
console.log('ZERO SAMPLE', JSON.stringify(zeroDetail.slice(0,3),null,2));
console.log('ZERO LAST', JSON.stringify(zeroDetail.slice(-2),null,2));

// any other usage fields anywhere
let otherUsage = 0;
for (const e of events) {
  const s = JSON.stringify(e);
  if (e.type!=='assistant/message' && /"inputTokens"|"usage"/.test(s)) otherUsage++;
}
console.log('other events mentioning usage/inputTokens', otherUsage);

